def build_lesson32():
    passages = []
    for name, stage, title, turns, lines in SPECS:
        targets = []
        for n, line in enumerate(lines.strip().splitlines(), 1):
            term, hint, form, meaning, distractors, review, review_form = line.split('|')
            targets.append(dict(id=f'l32_{name}_{n}', term=term, sense_hints=[hint], target=form,
                                meaning=meaning, distractors=distractors.split(';'),
                                review_text=review, review_target=review_form))
        passages.append(dict(id=f'vocab_l32_{name}', stage=stage, title=title, language='ru',
                             turns=[dict(speaker=s, text=t) for s, t in turns], targets=targets,
                             review_status='provisional', lesson='Lesson 32', module='Mod 6',
                             reference='Russian Basic Course, 2018 validation edition, Module VI, Lesson 32 glossary, printed pp. 85–88',
                             authoring='Original fictional study material; vocabulary alignment only; not official test content'))
    return passages
